const raw = (msg.payload && msg.payload.content ? msg.payload.content : msg.payload || '').toString().trim();
const chatId = msg.chatId || (msg.payload && msg.payload.chatId);

// Ігноруємо ТІЛЬКИ команди типу /start або системні кнопки меню
if (!raw || raw.startsWith('/') || raw === 'nbu' || raw === 'currency' || raw === 'operator') {
    return null;
}

// Занадто довгий ввід
if (raw.length > 50) {
    msg.payload = '⚠️ Занадто довгий вираз (макс 50 символів).';
    return msg;
}

// Перевірка на формат "число оператор число"
const match = raw.match(/^(-?\d+(?:[.,]\d+)?)\s*([+\-*xх×÷/])\s*(-?\d+(?:[.,]\d+)?)$/i);

if (!match) {
    msg.payload = `⚠️ Не розпізнав вираз "${raw}". Формат: число оператор число, напр. 12 + 7`;
    return msg;
}

const a = parseFloat(match[1].replace(',', '.'));
const op = match[2];
const b = parseFloat(match[3].replace(',', '.'));

let result;
switch (op) {
    case '+': result = a + b; break;
    case '-': result = a - b; break;
    case '*': case 'x': case 'х': case '×': result = a * b; break;
    case '/': case '÷':
        if (b === 0) {
            msg.payload = '⚠️ На нуль ділити не можна 🙂 Спробуй інший вираз.';
            return msg;
        }
        result = a / b;
        break;
}

msg.payload = `✅ Результат: ${a} ${op} ${b} = ${result}`;
return msg;

// Function node: "Unified Logger" — без змін у Calc Result!
const text = (msg.payload || '').toString();
const chatId = msg.originalMessage?.chat?.id || msg.chatId || 'unknown';
const time = new Date().toISOString();

let step = 'unknown';
let status = 'info';

if (text.startsWith('✅ Результат')) {
    step = 'calc:result';
    status = 'success';
} else if (text.includes('нуль')) {
    step = 'calc:validation_error';
    status = 'error';
} else if (text.includes('Не розпізнав') || text.includes('довгий')) {
    step = 'calc:validation_error';
    status = 'error';
}

node.warn(`[${time}] chat=${chatId} step=${step} status=${status} :: ${text}`);
return null;

// Function node: "Generate Support Ticket"
const chatId = msg.chatId || (msg.payload && msg.payload.chatId) || (msg.originalMessage && msg.originalMessage.chat.id);

const session = flow.get('session_' + chatId) || {};

const ticket = {
    ticket_id: `TCK-${Date.now()}`,
    timestamp: new Date().toISOString(),
    chat_id: chatId,
    reason: (session.errorCount && session.errorCount >= 3) ? '3_consecutive_errors' : 'manual_request',
    last_step: session.lastStep || 'menu',
    error_count: session.errorCount || 0,
    status: 'pending_operator'
};

session.errorCount = 0;
flow.set('session_' + chatId, session);

// Вихід 1: Об'єкт у стандарті RedBot для Telegram Sender
const replyMsg = {
    ...msg,
    chatId: chatId,
    payload: {
        type: 'message',
        content: `🆘 Бачу, що виникли труднощі. Переводжу тебе на оператора кол-центру.\n\nТікет *${ticket.ticket_id}* створено, з тобою зв'яжуться найближчим часом.`,
        chatId: chatId
    }
};

// Вихід 2: Запис для Unified Logger
const logMsg = {
    payload: {
        timestamp: ticket.timestamp,
        chatId: chatId,
        step: 'handoff:triggered',
        status: 'ok',
        summary: JSON.stringify(ticket)
    }
};

return [replyMsg, logMsg];

// Function node: "Format Currency" — 2 outputs
const chatId = msg.chatId || (msg.payload && msg.payload.chatId) || (msg.originalMessage && msg.originalMessage.chat && msg.originalMessage.chat.id);

function makeLog(step, status, summary) {
    return {
        payload: {
            timestamp: new Date().toISOString(),
            chatId: chatId,
            step: step,
            status: status,
            summary: summary
        }
    };
}

if (msg.statusCode !== 200 || !Array.isArray(msg.payload)) {
    const replyMsg = {
        ...msg,
        chatId: chatId,
        payload: {
            type: 'message',
            content: '⚠️ Не вдалося отримати курс, спробуйте пізніше.',
            chatId: chatId
        }
    };
    return [replyMsg, makeLog('nbu:error', 'error', `HTTP status ${msg.statusCode}`)];
}

const usd = msg.payload.find(item => item.cc === 'USD');
const eur = msg.payload.find(item => item.cc === 'EUR');

if (!usd || !eur) {
    const replyMsg = {
        ...msg,
        chatId: chatId,
        payload: {
            type: 'message',
            content: '⚠️ Не вдалося знайти потрібну валюту у відповіді НБУ.',
            chatId: chatId
        }
    };
    return [replyMsg, makeLog('nbu:error', 'error', 'USD or EUR not found in NBU response')];
}

const date = usd.exchangedate;

// Чистий гарний текст з емодзі без проблемних тегів
const text = `💵 Курс НБУ на ${date}:\n\n🇺🇸 USD: ${usd.rate.toFixed(2)} грн\n🇪🇺 EUR: ${eur.rate.toFixed(2)} грн`;

// Вихід 1: Напряму для Telegram Sender (як у тікеті!)
const replyMsg = {
    ...msg,
    chatId: chatId,
    payload: {
        type: 'message',
        content: text,
        chatId: chatId
    }
};

// Вихід 2: Лог
const logMsg = makeLog('nbu:request_sent', 'ok', `Fetched rates for ${date}`);

return [replyMsg, logMsg];

const chatId = msg.chatId || (msg.payload && msg.payload.chatId) || (msg.originalMessage && msg.originalMessage.chat && msg.originalMessage.chat.id);

flow.set('awaiting_' + chatId, 'calc');

return {
    ...msg,
    chatId: chatId,
    payload: {
        type: 'message',
        content: '🧮 Введіть математичний вираз для розрахунку (наприклад: 12 + 7 або 25 * 4):',
        chatId: chatId
    }
};
